mapper.select:

			SELECT DOC_TYPE||SUBSTR(YEAR,3,2)||LPAD(CUR_NO,6,0) 
              FROM ICOMSQMT
            WHERE COMPANY=#{COM_CODE} 
                AND DOC_TYPE=#{DOC_TYPE}

mapper.update:

			UPDATE ICOMSQMT 
				  SET YEAR = TO_CHAR(SYSDATE,'YYYY')
				  		, CUR_NO = CUR_NO+1
            WHERE COMPANY=#{COM_CODE} 
                AND DOC_TYPE=#{DOC_TYPE}
